{
  "name": "计算机键盘",
  "name_en": "Computer Keyboard",
  "manufacturer": "",
  "description": "标准计算机键盘，用于实验室控制计算机上的人工输入。它可让操作人员通过按键、快捷键或简单命令触发实验流程、设备控制或界面交互。",
  "description_en": "A standard computer keyboard used for manual input on a laboratory control computer. It allows an operator to trigger experiment workflows, device control, or interface interactions through key presses, hotkeys, or simple commands.",
  "tag_hints": [
    "keyboard input",
    "manual user input",
    "hotkeys",
    "operator console",
    "human-machine interaction"
  ],
  "actions": [
    {
      "action_name": "auto-run",
      "description": "运行键盘监听循环。",
      "description_en": "Run the keyboard listening loop."
    },
    {
      "action_name": "auto-start",
      "description": "开始监听键盘输入事件。",
      "description_en": "Start listening for keyboard input events."
    },
    {
      "action_name": "auto-stop",
      "description": "停止监听键盘输入事件。",
      "description_en": "Stop listening for keyboard input events."
    },
    {
      "action_name": "auto-run_keyboard",
      "description": "运行键盘输入处理任务。",
      "description_en": "Run the keyboard input handling task."
    }
  ]
}

